import type React from "react"
import type { ThemeType } from "../../theme/tokens"
import DeferredEmbed from "./DeferredEmbed"
import ProgressiveDetailImage from "./ProgressiveDetailImage"
import {
  getPdfLinkLabel,
  isPdfSource,
  parseTextWithLinks,
  type ProjectRecord,
} from "./projectDetail.shared"

interface ProjectDetailSectionsProps {
  project: ProjectRecord
  theme: ThemeType
}

const PAIR_IMAGE_SIZES = "(max-width: 700px) 46vw, 396px"
const QUAD_IMAGE_SIZES = "(max-width: 700px) 46vw, 198px"
const PHONE_IMAGE_SIZES = "(max-width: 700px) 46vw, 236px"

const isMp4Source = (source: string) => /\.mp4(?:$|[?#])/i.test(source)

const PhoneVideo: React.FC<{ src: string; title: string }> = ({ src, title }) => (
  <div className="project-detail-phone-video">
    <video
      controls
      muted
      loop
      playsInline
      preload="none"
      poster={src.replace(/\.mp4(?=$|[?#])/i, "_poster.jpg")}
      aria-label={title}
    >
      <source src={src} type="video/mp4" />
    </video>
  </div>
)

const ProjectDetailSections: React.FC<ProjectDetailSectionsProps> = ({ project, theme }) => {
  return (
    <>
      {project.sections.map((section, idx) => {
        if (section.text) {
          return (
            <p key={`txt-${idx}`} className="project-detail-paragraph">
              {parseTextWithLinks(section.text)}
            </p>
          )
        }

        if (section.videos?.length) {
          return (
            <div key={`vids-${idx}`} className="project-detail-phone-video-row">
              {section.videos.map((src) => (
                <PhoneVideo key={src} src={src} title={`${project.name} demo clip`} />
              ))}
            </div>
          )
        }

        if (section.video && isMp4Source(section.video)) {
          return (
            <div key={`vid-${idx}`} className="project-detail-phone-video-row">
              <PhoneVideo src={section.video} title={`${project.name} demo clip`} />
            </div>
          )
        }

        if (section.video) {
          if (isPdfSource(section.video)) {
            return (
              <a
                key={`pdf-${idx}`}
                className="project-detail-pdf-link"
                href={section.video}
                target="_blank"
                rel="noopener noreferrer"
              >
                {getPdfLinkLabel(section.video, project.name)}
              </a>
            )
          }

          return (
            <DeferredEmbed
              key={`vid-${idx}`}
              src={section.video}
              title={`${project.name} demo video`}
              theme={theme}
            />
          )
        }

        if (section.phoneImages?.length) {
          return (
            <div key={`phones-${idx}`} className="project-detail-phone-row">
              {section.phoneImages.map((src, imageIdx) => (
                <div key={src} className="project-detail-phone-frame">
                  <ProgressiveDetailImage
                    src={src}
                    alt={`${project.name} app screen ${idx + 1}.${imageIdx + 1}`}
                    sizes={PHONE_IMAGE_SIZES}
                    className="project-detail-phone-screen"
                  />
                </div>
              ))}
            </div>
          )
        }

        if (section.images?.length) {
          const isQuad = section.images.length >= 3
          return (
            <div
              key={`imgs-${idx}`}
              className={isQuad ? "project-detail-media-quad" : "project-detail-media-pair"}
            >
              {section.images.map((src, imageIdx) => (
                <div
                  key={src}
                  className={`project-detail-media-frame ${
                    isQuad
                      ? "project-detail-media-frame--quarter"
                      : "project-detail-media-frame--half"
                  }`}
                >
                  <ProgressiveDetailImage
                    src={src}
                    alt={`${project.name} screenshot ${idx + 1}.${imageIdx + 1}`}
                    sizes={isQuad ? QUAD_IMAGE_SIZES : PAIR_IMAGE_SIZES}
                  />
                </div>
              ))}
            </div>
          )
        }

        if (section.image) {
          return (
            <div
              key={`img-${idx}`}
              className="project-detail-media-frame project-detail-media-frame--section"
            >
              <ProgressiveDetailImage
                src={section.image}
                alt={`${project.name} screenshot ${idx + 1}`}
              />
            </div>
          )
        }

        return null
      })}
    </>
  )
}

export default ProjectDetailSections
